//! Small, editable starting points. Every visible shape is generated by its graph.

use crate::model::{Graph, NodeId, NodeKind};
use crate::persistence::Project;

pub struct Template {
    pub name: &'static str,
    pub description: &'static str,
    pub tag: &'static str,
}

pub const TEMPLATES: &[Template] = &[
    Template {
        name: "ねじれの花器",
        description: "ひだのある花器。半径・高さ・ねじりを動かして、自分の形へ。",
        tag: "はじめの作品",
    },
    Template {
        name: "光のリング",
        description: "球を円形に並べます。個数と間隔を変えるだけでリズムが生まれます。",
        tag: "くり返す",
    },
    Template {
        name: "星のトーテム",
        description: "星の輪郭を押し出してねじる、曲線から立体への基本。",
        tag: "立体にする",
    },
    Template {
        name: "螺旋のスケッチ",
        description: "半径・巻き数・高さから、空間を走る一本の曲線を作ります。",
        tag: "曲線を描く",
    },
    Template {
        name: "波打つブロック",
        description: "並べた箱を波のかたちに変形。入力が結果へ伝わる様子を試します。",
        tag: "形を変える",
    },
    Template {
        name: "輪郭からロフト",
        description: "数列で大きさと高さを変えた円をつなぎ、面を作ります。",
        tag: "データを使う",
    },
];

pub fn create(index: usize) -> Project {
    match build(index) {
        Ok(project) => project,
        Err(_) => Project::new("新しい作品", Graph::default()),
    }
}

fn add(
    graph: &mut Graph,
    kind: NodeKind,
    position: [f32; 2],
    params: &[(&str, f64)],
) -> Result<NodeId, String> {
    let id = graph.add(kind, position)?;
    if let Some(node) = graph.node_mut(id) {
        for &(key, value) in params {
            node.params.insert(key.to_string(), value);
        }
        node.preview = false;
    }
    Ok(id)
}

fn finish(graph: &mut Graph, from: NodeId, position: [f32; 2]) -> Result<(), String> {
    let output = graph.add(NodeKind::Output, position)?;
    graph.connect(from, output, "geometry")?;
    if let Some(node) = graph.node_mut(output) {
        node.preview = true;
    }
    Ok(())
}

fn build(index: usize) -> Result<Project, String> {
    let index = if index < TEMPLATES.len() { index } else { 0 };
    let mut graph = Graph::default();
    match index {
        0 => {
            let shape = add(
                &mut graph,
                NodeKind::Vase,
                [20.0, 30.0],
                &[
                    ("radius", 32.0),
                    ("height", 104.0),
                    ("thickness", 2.4),
                    ("lobes", 7.0),
                    ("amplitude", 0.18),
                    ("segments", 72.0),
                    ("layers", 40.0),
                ],
            )?;
            let twist = add(
                &mut graph,
                NodeKind::Twist,
                [290.0, 85.0],
                &[("angle", 110.0)],
            )?;
            graph.connect(shape, twist, "geometry")?;
            finish(&mut graph, twist, [290.0, 300.0])?;
        }
        1 => {
            let sphere = add(
                &mut graph,
                NodeKind::Sphere,
                [20.0, 30.0],
                &[("radius", 9.0), ("segments", 32.0), ("rings", 20.0)],
            )?;
            let moved = add(
                &mut graph,
                NodeKind::Move,
                [290.0, 30.0],
                &[("x", 65.0), ("z", 18.0)],
            )?;
            graph.connect(sphere, moved, "geometry")?;
            let array = add(
                &mut graph,
                NodeKind::RadialArray,
                [20.0, 320.0],
                &[("count", 10.0), ("angle", 360.0)],
            )?;
            graph.connect(moved, array, "geometry")?;
            finish(&mut graph, array, [290.0, 350.0])?;
        }
        2 => {
            let star = add(
                &mut graph,
                NodeKind::Star,
                [20.0, 30.0],
                &[("radius", 32.0), ("inner_radius", 19.0), ("points", 7.0)],
            )?;
            let extrude = add(
                &mut graph,
                NodeKind::Extrude,
                [290.0, 30.0],
                &[("height", 108.0), ("layers", 40.0)],
            )?;
            graph.connect(star, extrude, "curve")?;
            let twist = add(
                &mut graph,
                NodeKind::Twist,
                [20.0, 280.0],
                &[("angle", 145.0)],
            )?;
            graph.connect(extrude, twist, "geometry")?;
            finish(&mut graph, twist, [290.0, 305.0])?;
        }
        3 => {
            let helix = add(
                &mut graph,
                NodeKind::Helix,
                [60.0, 40.0],
                &[
                    ("radius", 30.0),
                    ("height", 110.0),
                    ("turns", 3.5),
                    ("segments", 256.0),
                ],
            )?;
            finish(&mut graph, helix, [330.0, 90.0])?;
        }
        4 => {
            let shape = add(
                &mut graph,
                NodeKind::Box,
                [20.0, 30.0],
                &[("width", 18.0), ("depth", 32.0), ("height", 14.0)],
            )?;
            let array = add(
                &mut graph,
                NodeKind::LinearArray,
                [290.0, 30.0],
                &[("count", 8.0), ("x", 26.0)],
            )?;
            graph.connect(shape, array, "geometry")?;
            let wave = add(
                &mut graph,
                NodeKind::Wave,
                [20.0, 340.0],
                &[("amplitude", 20.0), ("wavelength", 170.0)],
            )?;
            graph.connect(array, wave, "geometry")?;
            finish(&mut graph, wave, [290.0, 385.0])?;
        }
        _ => {
            let radii = add(
                &mut graph,
                NodeKind::Series,
                [20.0, 30.0],
                &[("start", 14.0), ("step", 3.0), ("count", 6.0)],
            )?;
            if let Some(n) = graph.node_mut(radii) {
                n.name = "円の大きさ".into();
            }
            let heights = add(
                &mut graph,
                NodeKind::Series,
                [20.0, 310.0],
                &[("start", 0.0), ("step", 20.0), ("count", 6.0)],
            )?;
            if let Some(n) = graph.node_mut(heights) {
                n.name = "円の高さ".into();
            }
            let circles = add(
                &mut graph,
                NodeKind::Circle,
                [262.0, 30.0],
                &[("segments", 64.0)],
            )?;
            graph.connect(radii, circles, "radius")?;
            let moved = add(&mut graph, NodeKind::Move, [504.0, 30.0], &[])?;
            graph.connect(circles, moved, "geometry")?;
            graph.connect(heights, moved, "z")?;
            let loft = add(&mut graph, NodeKind::Loft, [262.0, 310.0], &[])?;
            graph.connect(moved, loft, "curves")?;
            finish(&mut graph, loft, [504.0, 340.0])?;
        }
    }
    graph.validate()?;
    let mut project = Project::new(TEMPLATES[index].name, graph);
    project.pan = [24.0, 80.0];
    // Two-column examples stay readable in a laptop-sized graph panel. The
    // canvas fits these bounds to its actual size on the first visible frame.
    project.zoom = if index == 5 { 0.86 } else { 1.1 };
    Ok(project)
}
